package com.motionlayer.render
import androidx.compose.foundation.*; import androidx.compose.foundation.shape.*; import androidx.compose.material3.Text; import androidx.compose.runtime.Composable; import androidx.compose.ui.*; import androidx.compose.ui.draw.*; import androidx.compose.ui.graphics.*; import androidx.compose.ui.layout.ContentScale; import androidx.compose.ui.unit.*; import coil.compose.AsyncImage
import com.motionlayer.data.*
@Composable fun LayerRenderer(layer:Layer, modifier:Modifier=Modifier){ val m=modifier.offset{ androidx.compose.ui.unit.IntOffset((layer.x-120).toInt(),(layer.y-80).toInt()) }.graphicsLayer{scaleX=layer.scaleX;scaleY=layer.scaleY;rotationX=layer.rotationX;rotationY=layer.rotationY;rotationZ=layer.rotationZ;alpha=layer.opacity;cameraDistance=12f*density;shadowElevation=if(layer.style.shadowEnabled) layer.style.shadowBlur else 0f}.blur(layer.style.blur.dp)
 when(layer.type){ LayerType.TEXT-> Text(layer.text.orEmpty(), color=Color(layer.textStyle.color), fontSize=layer.textStyle.fontSize.sp, modifier=m.background(Color.Black.copy(.25f), RoundedCornerShape(8.dp)).padding(8.dp)); LayerType.SHAPE-> Box(m.size(180.dp,110.dp).background(Color(layer.shapeStyle.fillColor), if(layer.shapeType==ShapeType.CIRCLE) CircleShape else RoundedCornerShape(14.dp))); LayerType.IMAGE,LayerType.VIDEO-> AsyncImage(model=layer.sourceUri, contentDescription=layer.name, contentScale=ContentScale.Crop, modifier=m.size(220.dp,140.dp).clip(RoundedCornerShape(16.dp)).border(1.dp,Color.White.copy(.3f),RoundedCornerShape(16.dp))) }
}
